def send_telegram(msg):
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
    for i in range(0, len(msg), 3500):
        try:
            requests.post(url, data={'chat_id': CHAT_ID, 'text': msg[i:i+3500]}, timeout=20)
            time.sleep(0.3)
        except:
            pass

def check(s):
    try:
        df = yf.download(s, period='50d', interval='1d', progress=False, auto_adjust=True, threads=False)
        if len(df) < 40:
            return None
        c = float(df['Close'].iloc[-1])
        e20 = float(df['Close'].ewm(span=20).mean().iloc[-1])
        e50 = float(df['Close'].ewm(span=50).mean().iloc[-1])
        if c > e20 > e50:
            return f"✅ {s.replace('.NS','')} {c:.0f}"
    except:
        return None
    return None

sigs = []
with ThreadPoolExecutor(max_workers=20) as ex:
    futs = [ex.submit(check, s) for s in STOCKS]
    for f in as_completed(futs):
        r = f.result()
        if r:
            sigs.append(r)

date_str = datetime.now().strftime('%d-%m %H:%M')
if sigs:
    header = f"🚀 BOND 007 - {len(STOCKS)} SCAN 🚀\n📅 {date_str}\nBUY: {len(sigs)}\n\n"
    msg = header + "\n".join(sigs)
else:
    msg = f"📊 BOND 007 - {len(STOCKS)} SCAN\n📅 {date_str}\nNo BUY today"

print(msg)
send_telegram(msg)
